    let n = 0;
    while (a1 > a0 && b1 > b0 && a[a1-1] === b[b1-1]) { a1--; b1--; n++; }
    if (n > 0) stack.push({ eqFrom: a1, count: n });
    if (a0 === a1) {
      for (let j = b0; j < b1; j++) ops.push({ op: 'insert', line: b[j] });
    } else if (b0 === b1) {
