function diffLines(a, b) {
  const ops = [];
  const stack = [{ a0: 0, a1: a.length, b0: 0, b1: b.length }];
  while (stack.length) {
    const t = stack.pop();
    if (t.eqFrom !== undefined) {
      for (let i = 0; i < t.count; i++) ops.push({ op: 'equal', line: a[t.eqFrom + i] });
      continue;
    }
    let { a0, a1, b0, b1 } = t;
    while (a0 < a1 && b0 < b1 && a[a0] === b[b0]) { ops.push({op:'equal',line:a[a0]}); a0++; b0++; }
    let n = 0;
    while (a1 > a0 && b1 > b0 && a[a1-1] === b[b1-1]) { a1--; b1--; n++; }
    if (n > 0) stack.push({ eqFrom: a1, count: n });
    if (a0 === a1) {
      for (let j = b0; j < b1; j++) ops.push({ op: 'insert', line: b[j] });
    } else if (b0 === b1) {
      for (let i = a0; i < a1; i++) ops.push({ op: 'delete', line: a[i] });
    } else {
      const ms = findMiddleSnake(a, a0, b, b0, a1 - a0, b1 - b0);
      stack.push({ a0: ms.rx, a1, b0: ms.ry, b1 });
      stack.push({ a0, a1: ms.lx, b0, b1: ms.ly });
    }
  }
  // enforce deletes before inserts within changed regions
  const out = [];
  let i = 0;
  while (i < ops.length) {
    if (ops[i].op === 'equal') { out.push(ops[i]); i++; }
    else {
      let j = i;
      while (j < ops.length && ops[j].op !== 'equal') j++;
      for (let k=i;k<j;k++) if (ops[k].op==='delete') out.push(ops[k]);
      for (let k=i;k<j;k++) if (ops[k].op==='insert') out.push(ops[k]);
      i = j;
    }
  }
  return out;
}
```

