function findMiddleSnake(a, a0, b, b0, N, M) {
  // a0..a0+N, b0..b0+M, N>0, M>0
  const delta = N - M;
  const odd = (delta & 1) !== 0;
  const off = N + M + 1;
  const vf = new Int32Array(2 * (N + M) + 3);
  const vb = new Int32Array(2 * (N + M) + 3);
  vf[off + 1] = 0;
  vb[off + delta - 1] = N;
  const dmax = Math.ceil((N + M) / 2);
  for (let d = 0; d <= dmax; d++) {
    for (let k = -d; k <= d; k += 2) {
      let x;
      if (k === -d || (k !== d && vf[off + k - 1] < vf[off + k + 1])) x = vf[off + k + 1];
      else x = vf[off + k - 1] + 1;
      let y = x - k;
      const x0 = x, y0 = y;
      while (x < N && y < M && a[a0 + x] === b[b0 + y]) { x++; y++; }
      vf[off + k] = x;
      if (odd && k >= delta - (d - 1) && k <= delta + (d - 1) && vf[off + k] >= vb[off + k]) {
        return { lx: a0 + x0, ly: b0 + y0, rx: a0 + x, ry: b0 + y };
      }
    }
    for (let k = -d; k <= d; k += 2) {
      const kr = k + delta;
      let x;
      if (k === -d || (k !== d && vb[off + kr - 1] < vb[off + kr + 1])) x = vb[off + kr - 1];
      else x = vb[off + kr + 1] - 1;
      let y = x - kr;
      const x1 = x, y1 = y;
      while (x > 0 && y > 0 && a[a0 + x - 1] === b[b0 + y - 1]) { x--; y--; }
      vb[off + kr] = x;
      if (!odd && kr >= -d && kr <= d && vb[off + kr] <= vf[off + kr]) {
        return { lx: a0 + x, ly: b0 + y, rx: a0 + x1, ry: b0 + y1 };
      }
    }
  }
