const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcsLen(a, b) {
  // O(N*M) reference for small inputs
  const dp = Array.from({length: a.length+1}, () => new Array(b.length+1).fill(0));
  for (let i=a.length-1;i>=0;i--) for (let j=b.length-1;j>=0;j--)
    dp[i][j] = a[i]===b[j] ? dp[i+1][j+1]+1 : Math.max(dp[i+1][j], dp[i][j+1]);
  return dp[0][0];
}

function checkOps(a, b, ops) {
  const ra = ops.filter(o=>o.op!=='insert').map(o=>o.line);
  const rb = ops.filter(o=>o.op!=='delete').map(o=>o.line);
  assert.deepEqual(ra, a, 'reconstruct a');
  assert.deepEqual(rb, b, 'reconstruct b');
  const dels = ops.filter(o=>o.op==='delete').length;
  const ins = ops.filter(o=>o.op==='insert').length;
  assert.equal(dels+ins, a.length+b.length-2*lcsLen(a,b), 'minimal');
  // deletes before inserts within changed regions
  let regionIns = false;
  for (const o of ops) {
    if (o.op==='equal') { regionIns=false; continue; }
    if (o.op==='insert') regionIns=true;
    if (o.op==='delete') assert(!regionIns, 'delete after insert in region');
  }
}

// Randomized property tests including heavy repetition
const alphabetSets = [['x'], ['', 'x'], ['a','b'], ['a','b','c','d'], [' ','-','+','  indent','line']];
let seed = 42;
const rand = () => (seed = (seed*1103515245+12345) & 0x7fffffff) / 0x80000000;
for (let trial = 0; trial < 2000; trial++) {
  const alph = alphabetSets[trial % alphabetSets.length];
  const mk = () => Array.from({length: Math.floor(rand()*12)}, () => alph[Math.floor(rand()*alph.length)]);
  const a = mk(), b = mk();
  const ops = diffLines(a, b);
  checkOps(a, b, ops);
  // roundtrip via unifiedHunks at several contexts
  for (const context of [0, 1, 2, 3, 5]) {
    const hunks = unifiedHunks(a, b, { context });
    // verify hunk coordinate/count sanity
    for (const h of hunks) {
      const co = h.lines.filter(l=>l[0]===' '||l[0]==='-').length;
      const cn = h.lines.filter(l=>l[0]===' '||l[0]==='+').length;
      assert.equal(co, h.oldLines); assert.equal(cn, h.newLines);
    }
    assert.deepEqual(applyHunks(a, hunks), b, 'roundtrip ctx='+context);
  }
  // identical inputs
  assert.deepEqual(unifiedHunks(a, a), []);
  assert.deepEqual(applyHunks(a, []), a);
}

// Mutated-input check
const a0 = ['a','b'], b0 = ['a','c'];
diffLines(a0, b0); unifiedHunks(a0, b0); applyHunks(a0, unifiedHunks(a0,b0));
assert.deepEqual(a0, ['a','b']); assert.deepEqual(b0, ['a','c']);

// applyHunks error cases
assert.throws(() => applyHunks(['a'], [{oldStart:1,oldLines:1,newStart:1,newLines:1,lines:[' wrong']}]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(['a'], [{oldStart:1,oldLines:2,newStart:1,newLines:2,lines:[' a','+b']}]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(['a'], [{oldStart:1,oldLines:1,newStart:5,newLines:1,lines:[' a']}]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(['a'], [{oldStart:1,oldLines:1,newStart:1,newLines:1,lines:['?a']}]), /hunk 0 does not apply/);
// overlapping hunks
const a2 = ['a','b','c'];
const hBad = [
  {oldStart:1,oldLines:2,newStart:1,newLines:2,lines:[' a',' b']},
  {oldStart:2,oldLines:1,newStart:2,newLines:1,lines:[' b']},
];
assert.throws(() => applyHunks(a2, hBad), /hunk 1 does not apply/);

// insertion at top / deletion at top coordinate rules
const aI = ['x'], bI = ['new','x'];
assert.deepEqual(unifiedHunks(aI, bI, {context:0}), [{oldStart:0,oldLines:0,newStart:1,newLines:1,lines:['+new']}]);
assert.deepEqual(applyHunks(aI, unifiedHunks(aI,bI,{context:0})), bI);
const aD = ['gone','x'], bD = ['x'];
assert.deepEqual(unifiedHunks(aD, bD, {context:0}), [{oldStart:1,oldLines:1,newStart:0,newLines:0,lines:['-gone']}]);
assert.deepEqual(applyHunks(aD, unifiedHunks(aD,bD,{context:0})), bD);
// pure insertion in middle
const aM = ['a','b'], bM = ['a','m1','m2','b'];
assert.deepEqual(unifiedHunks(aM, bM, {context:0}), [{oldStart:1,oldLines:0,newStart:2,newLines:2,lines:['+m1','+m2']}]);
// empty inputs
assert.deepEqual(diffLines([], []), []);
assert.deepEqual(diffLines([], ['a']), [{op:'insert',line:'a'}]);
assert.deepEqual(diffLines(['a'], []), [{op:'delete',line:'a'}]);
assert.deepEqual(unifiedHunks([], [], {}), []);
assert.deepEqual(applyHunks([], unifiedHunks([],['q'],{context:0})), ['q']);

// lines that themselves start with prefixes
const aP = ['-already', '+plus', ' spaced'];
const bP = ['+plus', '-already', ' spaced'];
assert.deepEqual(applyHunks(aP, unifiedHunks(aP, bP, {context:3})), bP);

// Performance: 20k lines, small change
const big = Array.from({length:20000}, (_,i)=>'line '+i);
const big2 = big.slice(); big2[10000] = 'changed'; big2.splice(5000, 0, 'added1','added2'); big2.splice(15000, 3);
let t = process.hrtime.bigint();
const opsBig = diffLines(big, big2);
let ms = Number(process.hrtime.bigint()-t)/1e6;
checkOps(big, big2, opsBig);
t = process.hrtime.bigint();
const hBig = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hBig), big2);
ms = Math.max(ms, Number(process.hrtime.bigint()-t)/1e6);
console.log('perf 20k small change:', ms.toFixed(1), 'ms');
assert(ms < 500, 'too slow');

// Performance: repetitive lines
const rep1 = Array.from({length:20000}, ()=>'same');
const rep2 = Array.from({length:19999}, ()=>'same');
t = process.hrtime.bigint();
const opsR = diffLines(rep1, rep2);
ms = Number(process.hrtime.bigint()-t)/1e6;
checkOps(rep1, rep2, opsR);
console.log('perf repetitive:', ms.toFixed(1), 'ms');
assert(ms < 500);

// scattered repetitive changes
const s1 = Array.from({length:10000}, (_,i)=> i%3===0 ? 'dup' : 'u'+i);
const s2 = s1.slice();
for (let i=0;i<s2.length;i+=97) s2[i]='dup';
t = process.hrtime.bigint();
const opsS = diffLines(s1, s2);
ms = Number(process.hrtime.bigint()-t)/1e6;
checkOps(s1, s2, opsS);
console.log('perf scattered:', ms.toFixed(1), 'ms');
assert(ms < 1000);

console.log('all property checks passed');
"

