        vf[off + k] = x;
        if (odd && k >= delta - (d - 1) && k <= delta + (d - 1) && x >= vb[off + k]) {
          return { x: a0 + x0, y: b0 + y0 };
        }
      }
    }

    // Reverse furthest-reaching paths from (N, M), kr = x - y in [-M, N].
    let rLo = Math.max(delta - d, -M);
    if (((rLo - delta - d) & 1) !== 0) rLo++;
    let rHi = Math.min(delta + d, N);
    if (((rHi - delta - d) & 1) !== 0) rHi--;
    for (let kr = rLo; kr <= rHi; kr += 2) {
